package kome.common.data;
/** Read-only canonical progression-book projection. */
public final class KOMEProgressionSummary { private KOMEProgressionSummary(){} public static String text(KOMEPlayerProgression p){KOMESerfKnightProgression s=p.getSerfKnightProgression();String r="Rank: "+p.getCanonicalRank().displayName;if(p.getCanonicalRank()!=KOMEProgressionRank.SERF)return r;if(!s.getSerfdomMaster().isSet())return r+"\nChoose an ordinary NPC of your pledged faction as Serfdom Master.\nSneak-right-click an eligible NPC to begin service.";if(s.getActiveAssignmentKind().length()!=0)return r+"\nSerfdom Master: "+s.getSerfdomMaster().displayName+"\nCurrent Duty: "+s.getActiveAssignmentKind();if(s.isTrialCompleted()&&!s.hasPartingGift())return r+"\nTrial complete. Return to your Serfdom Master for your parting gift.";if(KOMESerfKnightService.allDutiesComplete(s)&&!s.getProspectiveLiege().isSet())return r+"\nSerfdom complete. Find an eligible Lord as prospective liege.";return r+"\nSerfdom Master: "+s.getSerfdomMaster().displayName+"\nSpeak to your master for today's duty.";} public static String findLabel(KOMEPlayerProgression p){KOMESerfKnightProgression s=p.getSerfKnightProgression();if(p.getCanonicalRank()==KOMEProgressionRank.SERF&&s.getSerfdomMaster().isSet())return "Find Master";if(s.getProspectiveLiege().isSet())return "Find Liege";return p.hasPledgedLord()?"Find Lord":"";} }
